command:
$ErrorActionPreference = "Stop"
git fetch origin main control/remote-shell --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch refs failed" }
if ((git rev-parse origin/main).Trim() -ne "118b92c77c5ca8a78207b5236c42fa688796d108") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }

git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "fast-forward main failed" }
if ((git rev-parse HEAD).Trim() -ne "118b92c77c5ca8a78207b5236c42fa688796d108") { throw "main mismatch" }

python -X utf8 -m py_compile tests\winui\test_remote_windows_task_contract.py
if ($LASTEXITCODE -ne 0) { throw "contract syntax failed" }
python -X utf8 tests\winui\test_remote_windows_task_contract.py
if ($LASTEXITCODE -ne 0) { throw "remote workflow contract failed" }
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

$triggerLines = @(git show origin/control/remote-shell:.github/workflows/remote-windows-task.yml)
if ($LASTEXITCODE -ne 0) { throw "control trigger read failed" }
$trigger = $triggerLines -join [Environment]::NewLine
if ($trigger -notmatch 'uses:\s+tngkrwlsmd/flyExplorer/.github/workflows/remote-windows-task.yml@main') {
  throw "control trigger does not delegate to main reusable workflow"
}
if ($trigger -match 'validation_kind|Invoke-Expression|upload-artifact|runs-on:|FLYEXPLORER_CANONICAL_CHECKOUT') {
  throw "control trigger contains duplicated execution logic"
}
$implementation = Get-Content -Raw -Encoding UTF8 .github\workflows\remote-windows-task.yml
if ($implementation -notmatch 'workflow_call:' -or $implementation -match '(?m)^\s{2}push:') {
  throw "main implementation ownership contract failed"
}

git diff --check HEAD^..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "REMOTE_WORKFLOW_SINGLE_SOURCE_PASS"
